(()=>{'use strict';
const $=s=>document.querySelector(s),el=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e;};
let state,dirty=false,busy=false;
async function api(path,body){const r=await fetch('/api/admin/'+path,{cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Не удалось выполнить запрос.');return d;}
const groups=[
 ['Касса', [['Исправить начальный остаток',()=>window.STARTWork.opening()]]],
 ['aQsi CS50', [['Подключение кассы','/admin/aqsi/?settings=aqsi']]],
 ['Прокат',[['Порядок техники','#fleet-settings'],['Тарифы, часы работы и бронирование','/admin/?settings=content'],['Состояние аккумуляторов','/admin/battery-state/?settings=batteries']]],
 ['Кафе',[['Товары: фото, варианты, расход и себестоимость','/admin/cafe/?settings=menu'],['Приём заказов, доставка и время работы','/admin/cafe/?settings=settings'],['Столы, места, QR и NFC','/admin/cafe/?settings=places'],['Выгрузка заказов','/admin/cafe/?settings=management']]],
 ['Склад',[['Товары, категории, единицы и минимальные остатки','/admin/purchase/?settings=inventory']]],
 ['Сотрудники и зарплата',[['Смены и зарплата','/admin/workforce/'],['График на неделю','/admin/schedule/'],['Создать сотрудника и выбрать роль','/admin/workforce/?settings=people'],['Учётные записи и пароли','/admin/accounts/?settings=accounts'],['Правила расчёта зарплаты','/admin/workforce/?settings=salary']]],
 ['Уведомления и печать',[['Telegram владельцу','/admin/workforce/?settings=telegram'],['SMS Aero и напоминания','/admin/?settings=sms'],['Принтер и отчёты смены','/admin/workforce/?settings=print']]],
 ['Сайт',[['Тексты, фотографии, контакты и SEO','/admin/?settings=content']]],
 ['Дела',[['Пункты чек-листов открытия, работы и закрытия','/admin/tasks/?settings=tasks']]]
];
function renderGroup(root,title,links){const box=el('section','');if(title==='Кафе')box.id='cafe';box.append(el('h2',title));for(const [label,target] of links){if(typeof target==='function'){const button=el('button',label),error=el('p','');button.type='button';button.className='settings-action';error.className='settings-action-error';error.setAttribute('role','status');button.onclick=async()=>{if(button.disabled)return;button.disabled=true;error.textContent='';try{await target();}catch(e){error.textContent=e.message||'Не удалось открыть действие. Попробуйте ещё раз.';}finally{button.disabled=false;}};box.append(button,error);}else{const a=el('a',label+' →');a.href=target;box.append(a);}}root.append(box);}
function render(){const out=$('#fleet-order');out.replaceChildren();state.items.forEach((item,i)=>{const row=el('li',''),name=el('span',item.label);row.append(name);for(const [offset,label] of [[-1,'↑'],[1,'↓']]){const b=el('button',label);b.type='button';b.disabled=busy||i+offset<0||i+offset>=state.items.length;b.setAttribute('aria-label',(offset<0?'Поднять: ':'Опустить: ')+item.label);b.onclick=()=>{[state.items[i],state.items[i+offset]]=[state.items[i+offset],state.items[i]];dirty=true;render();$('#fleet-message').textContent='Порядок изменён — нажмите «Сохранить порядок».';out.children[i+offset].querySelector(offset<0?'button':'button:last-child').focus();};row.append(b);}out.append(row);});$('#fleet-save').disabled=busy||!dirty;$('#fleet-reload').disabled=busy;}
async function load(){state=await api('fleet-order');dirty=false;render();}
$('#fleet-reload').onclick=async()=>{if(dirty&&!confirm('Отбросить несохранённый порядок и загрузить сохранённый?'))return;try{await load();$('#fleet-message').textContent='Список обновлён.';}catch(e){$('#fleet-message').textContent=e.message;}};
$('#fleet-save').onclick=async()=>{if(busy||!dirty)return;busy=true;render();try{state=await api('fleet-order',{revision:state.revision,ids:state.items.map(x=>x.id)});dirty=false;$('#fleet-message').textContent='Порядок сохранён для всех сотрудников.';}catch(e){$('#fleet-message').textContent=e.message+' При ошибке связи обновите список, чтобы проверить сохранение.';}finally{busy=false;render();}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
(async()=>{try{const {user}=await api('session');if(!user){$('#settings-notice').textContent='Войдите, чтобы открыть настройки.';$('#settings-login').hidden=false;return;}const root=$('#settings-groups');root.hidden=false;if(user.role!=='admin'){renderGroup(root,'Моя работа',[['Смены и зарплата','/admin/workforce/'],['График на неделю','/admin/schedule/'],['Изменить свой пароль','/admin/accounts/?settings=accounts']]);if(['staff','waiter'].includes(user.role))renderGroup(root,'Кафе',[['Товары: фото, варианты, расход и себестоимость','/admin/cafe/?settings=menu']]);$('#settings-notice').textContent='Личные настройки и доступные разделы работы. Общие настройки станции доступны администратору.';return;}$('#settings-notice').textContent='Все настройки станции в одном месте.';for(const [title,links] of groups)renderGroup(root,title,links);$('#fleet-settings').hidden=false;await load();if(location.hash==='#fleet-settings')$('#fleet-settings').scrollIntoView();}catch(e){$('#settings-notice').textContent=e.message;}})();
})();
